// KnowledgeServiceServer is the server API for KnowledgeService service.
// All implementations must embed UnimplementedKnowledgeServiceServer
// for forward compatibility.
type KnowledgeServiceServer interface {
	// Collections
	CreateCollection(context.Context, *CreateCollectionRequest) (*KnowledgeCollection, error)
	GetCollection(context.Context, *GetCollectionRequest) (*KnowledgeCollection, error)
	ListCollections(context.Context, *ListCollectionsRequest) (*ListCollectionsResponse, error)
	DeleteCollection(context.Context, *DeleteCollectionRequest) (*emptypb.Empty, error)
	// Documents
	IngestDocument(context.Context, *IngestDocumentRequest) (*KnowledgeDocument, error)
	ListDocuments(context.Context, *ListDocumentsRequest) (*ListDocumentsResponse, error)
	GetDocumentContent(context.Context, *GetDocumentContentRequest) (*DocumentContent, error)
	DeleteDocument(context.Context, *DeleteDocumentRequest) (*emptypb.Empty, error)
	MoveDocument(context.Context, *MoveDocumentRequest) (*KnowledgeDocument, error)
	// MoveDocumentToDir moves a vault document to another directory within the same
	// collection (G3-B4): atomic fs move + rel_path update (identity/chunks kept) +
	// inbound explicit links rebuild. Name clash -> CodeConflict unless
	// conflict_policy=overwrite|rename. Vault documents only (rel_path required).
	MoveDocumentToDir(context.Context, *MoveDocumentToDirRequest) (*KnowledgeDocument, error)
	// ReembedDocuments re-chunks and re-embeds documents from their stored
	// content_text (B1: heals UI-uploaded docs whose embeddings were nulled by
	// reconcileEmbeddingDim; vault docs self-heal via vault_sync and are skipped).
	ReembedDocuments(context.Context, *ReembedDocumentsRequest) (*ReembedDocumentsResponse, error)
	// EnableCollectionSemantic one-way enables the semantic layer on a lexical-only
	// collection (B2): binds the current global embedder model/dim (guarded UPDATE,
	// conflict when already enabled) and enqueues all content documents into the
	// B1 re-embed pipeline. CodeBadRequest when the embedder is not configured.
	EnableCollectionSemantic(context.Context, *EnableCollectionSemanticRequest) (*EnableCollectionSemanticResponse, error)
	// UpdateDocumentContent saves editor body back to the vault file (G2-B5):
	// frontmatter preserved, CAS via base_hash; conflict still writes (disk copy
	// backed up to trash) and returns conflict=true. Triggers immediate reindex.
	UpdateDocumentContent(context.Context, *UpdateDocumentContentRequest) (*UpdateDocumentContentResponse, error)
	// Vault explorer (P3): lazy folder listing derived from document rel_paths.
	ListVaultTree(context.Context, *ListVaultTreeRequest) (*ListVaultTreeResponse, error)
	// CreateVaultDir creates a directory inside the vault (G1-B2; idempotent).
	CreateVaultDir(context.Context, *CreateVaultDirRequest) (*emptypb.Empty, error)
	// CreateVaultDocument writes a template .md (frontmatter + empty heading) and
	// indexes it immediately (G1-B2; no 45s poll wait). Existing path = conflict.
	CreateVaultDocument(context.Context, *CreateVaultDocumentRequest) (*KnowledgeDocument, error)
	// Document relations with source-type annotation (P3 关联区, R-3).
	ListDocumentLinks(context.Context, *ListDocumentLinksRequest) (*ListDocumentLinksResponse, error)
	// ListCollectionGraph returns the full link graph of one collection (G4-B8):
	// nodes = documents (after path_prefix filter), edges = links (link_types filter;
	// endpoints outside scope/dangling dropped), degree = in-edge count per node.
	ListCollectionGraph(context.Context, *ListCollectionGraphRequest) (*ListCollectionGraphResponse, error)
	// ListDocumentNeighborhood returns the N-hop undirected neighborhood subgraph
	// of one document (SP2-8 右栏局部图): same node/edge shape as the full graph,
	// but only the small vicinity is transferred (large-vault friendly).
	ListDocumentNeighborhood(context.Context, *ListDocumentNeighborhoodRequest) (*ListCollectionGraphResponse, error)
	// ListBlockBacklinks returns block-level inbound references (SP1-E): context
	// excerpt + source block/document per edge. Single block via block_id path;
	// aggregate all blocks of a document via the doc_id binding.
	ListBlockBacklinks(context.Context, *ListBlockBacklinksRequest) (*ListBlockBacklinksResponse, error)
	// ListDanglingLinks aggregates dangling references of one collection by
	// raw_target with ref counts (SP1-E; "uncreated notes" view).
	ListDanglingLinks(context.Context, *ListDanglingLinksRequest) (*ListDanglingLinksResponse, error)
	// ListUnlinkedMentions returns documents that mention the target doc's name
	// in plain text (outside [[wikilinks]]) without linking to it (P2-7).
	ListUnlinkedMentions(context.Context, *ListUnlinkedMentionsRequest) (*ListUnlinkedMentionsResponse, error)
	// RecordLinkUse upserts the (collection, doc) recency row when a wikilink
	// completion is applied (B4 #8); best-effort, callers may ignore failures.
	RecordLinkUse(context.Context, *RecordLinkUseRequest) (*RecordLinkUseResponse, error)
	// ListRecentLinkUses returns recently used wikilink targets of one
	// collection, most recent first (B4 #8); drives empty-query [[ completion
	// ordering on the client.
	ListRecentLinkUses(context.Context, *ListRecentLinkUsesRequest) (*ListRecentLinkUsesResponse, error)
	// PromoteBlocks clones blocks from a personal vault into a team collection
	// (SP1-G, US-27): copy-not-move with lineage pair (promoted_from/promoted_to),
	// cascade candidates for references into private blocks, and immediate
	// re-indexing of the target document so promoted content is searchable.
	PromoteBlocks(context.Context, *PromoteBlocksRequest) (*PromoteBlocksResponse, error)
	// RebuildKnowledgeIndex rebuilds the block-level derived index (blocks/refs)
	// for every document of the collection (SP1-H, US-29). Asynchronous and
	// idempotent; 409 Conflict while a rebuild is already running for the same
	// collection. Progress via knowledge WS events (EP-KN-02 pattern); chunks/FTS
	// stay on old data during the rebuild (degraded but available).
	RebuildKnowledgeIndex(context.Context, *RebuildKnowledgeIndexRequest) (*RebuildKnowledgeIndexResponse, error)
	// ListEntityMergeSuggestions lists entity merge candidates (G5-F B11):
	// normalization conflict groups (same name_norm, different display name)
	// plus high-similarity embedding pairs when the embedder is configured.
	// Computed in real time; no queue table.
	ListEntityMergeSuggestions(context.Context, *ListEntityMergeSuggestionsRequest) (*ListEntityMergeSuggestionsResponse, error)
	// MergeKnowledgeEntities merges mergee entities into the keeper (G5-F B10)
	// atomically; returns rewrite counts for inline UI feedback.
	MergeKnowledgeEntities(context.Context, *MergeKnowledgeEntitiesRequest) (*MergeKnowledgeEntitiesResponse, error)
	// ListGovernanceProposals lists curation governance proposals (M4 自治理层
	// 人工二审出口): high-risk conflict/orphan proposals wait here for human review.
	ListGovernanceProposals(context.Context, *ListGovernanceProposalsRequest) (*ListGovernanceProposalsResponse, error)
	// ResolveGovernanceProposal closes one pending proposal (人工二审):
	// decision=applied approves the action; rejected dismisses it;
	// keep_old/keep_new resolve fact-level conflicts by choosing which section to keep.
	ResolveGovernanceProposal(context.Context, *ResolveGovernanceProposalRequest) (*ResolveGovernanceProposalResponse, error)
	// Search
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	GetEmbedderConfig(context.Context, *GetEmbedderConfigRequest) (*EmbedderConfig, error)
	UpdateEmbedderConfig(context.Context, *UpdateEmbedderConfigRequest) (*UpdateEmbedderConfigResponse, error)
	mustEmbedUnimplementedKnowledgeServiceServer()
}

